import { test } from '@playwright/test';

import { loginAs } from '../bazis';

import { PRODUCT } from './product';

test('manager-cannot-change-the-report', async ({ page }) => {
  const app = await loginAs(page, PRODUCT, 'manager');
  await test.step('open: task-list', async () => {
    await app.open('task-list');
  });
  await test.step('action: create', async () => {
    await app.action('create');
  });
  await test.step('fill: {title: Draft the report}', async () => {
    await app.fill({ title: 'Draft the report' });
  });
  await test.step('submit', async () => {
    await app.submit();
    await app.expectScreen('task-card');
  });
  await test.step('expect: {screen: task-card, status: draft, field_readonly: report}', async () => {
    await app.expectScreen('task-card');
    await app.expectStatus('draft');
    await app.expectFieldReadonly('report');
  });
});
